import sys

def pos(s, a, b, c, k):
    ret = 0
    for x in s:
        if x == 'V':
            if a == 0:
                if k == 0:
                    return ret
                ret += 1
            else:
                a -= 1
        elif x == 'K':
            if b == 0:
                if k == 1:
                    return ret
                ret += 1
            else:
                b -= 1
        else:
            if c == 0:
                if k == 2:
                    return ret
                ret += 1
            else:
                c -= 1
    return -1

def main():
    input = sys.stdin.read().splitlines()
    n = int(input[0].strip())
    s = list(input[1])

    import math
    MAX = math.inf

    vCount = s.count('V')
    kCount = s.count('K')
    eCount = s.count('E')  # Note: original code treats other chars as 'E'
    # But in original code, only 'V', 'K', and others are considered.
    # So, for other characters, count as 'E' for simplicity.
    # Since original code treats all other characters as 'E', we can do:
    # eCount = total length - vCount - kCount
    eCount = n - vCount - kCount

    # Initialize dp array
    dp = [[[[MAX for _ in range(eCount+1)] for _ in range(kCount+1)] for _ in range(vCount+1)] for _ in range(3)]
    # Initialize poss array
    poss = [[[[0 for _ in range(eCount+1)] for _ in range(kCount+1)] for _ in range(vCount+1)] for _ in range(3)]

    for l in range(3):
        for i in range(vCount+1):
            for j in range(kCount+1):
                for k in range(eCount+1):
                    poss[l][i][j][k] = pos(s, i, j, k, l)

    # Set starting point
    dp[2][0][0][0] = 0

    for i in range(vCount+1):
        for j in range(kCount+1):
            for k in range(eCount+1):
                for l in range(3):
                    if dp[l][i][j][k] == MAX:
                        continue
                    current_cost = dp[l][i][j][k]
                    # Try to pick 'V'
                    if i + 1 <= vCount and poss[0][i][j][k] != -1:
                        v = poss[0][i][j][k]
                        new_cost = current_cost + v
                        if new_cost < dp[0][i+1][j][k]:
                            dp[0][i+1][j][k] = new_cost
                    # Try to pick 'K'
                    if j + 1 <= kCount and poss[1][i][j][k] != -1:
                        v = poss[1][i][j][k]
                        new_cost = current_cost + v
                        if new_cost < dp[1][i][j+1][k]:
                            dp[1][i][j+1][k] = new_cost
                    # Try to pick 'E'
                    if k + 1 <= eCount and poss[2][i][j][k] != -1:
                        v = poss[2][i][j][k]
                        for next_l in [0,1,2]:
                            new_cost = current_cost + v
                            if new_cost < dp[next_l][i][j][k+1]:
                                dp[next_l][i][j][k+1] = new_cost
    result = min(dp[0][vCount][kCount][eCount], dp[1][vCount][kCount][eCount], dp[2][vCount][kCount][eCount])
    print(result)

if __name__ == "__main__":
    main()

